import { isAbsolute, resolve } from 'path'

export interface RuntimeContext {
  workspaceRoot: string
  builtinRoot: string
  pluginRoot: string
  cacheFilePath: string
}

export interface RuntimeContextInput {
  cwd?: string
  workspaceRoot?: string
  builtinRoot?: string
  pluginRoot?: string
  cacheFilePath?: string
}

function resolveFromWorkspace(workspaceRoot: string, pathValue: string | undefined, fallbackRelative: string): string {
  if (!pathValue || pathValue.trim().length === 0) {
    return resolve(workspaceRoot, fallbackRelative)
  }
  if (isAbsolute(pathValue)) {
    return resolve(pathValue)
  }
  return resolve(workspaceRoot, pathValue)
}

export function resolveRuntimeContext(input: RuntimeContextInput = {}): RuntimeContext {
  const baseCwd = input.cwd ?? process.cwd()
  const workspaceRoot = input.workspaceRoot
    ? resolve(baseCwd, input.workspaceRoot)
    : resolve(baseCwd)

  return {
    workspaceRoot,
    builtinRoot: resolveFromWorkspace(workspaceRoot, input.builtinRoot, 'builtin'),
    pluginRoot: resolveFromWorkspace(workspaceRoot, input.pluginRoot, 'plugins'),
    cacheFilePath: resolveFromWorkspace(
      workspaceRoot,
      input.cacheFilePath,
      '.neo-designer/state/workflow-registry-cache.json',
    ),
  }
}

import { test } from 'node:test'
import { strict as assert } from 'node:assert'
import { dirname, resolve } from 'path'
import { fileURLToPath } from 'url'
import { resolveRuntimeContext } from './runtimeContext.ts'

const TEST_DIR = dirname(fileURLToPath(import.meta.url))
const PACKAGE_ROOT = resolve(TEST_DIR, '..', '..', '..')


test('default builtinRoot resolves relative to package root, not workspace root', () => {
  const cwd = '/tmp/neo-test-workspace'
  const ctx = resolveRuntimeContext({ cwd })
  assert.equal(ctx.builtinRoot, resolve(PACKAGE_ROOT, 'builtin'))
  assert.notEqual(ctx.builtinRoot, resolve(ctx.workspaceRoot, 'builtin'))
})

