import { dirname, isAbsolute, resolve } from 'path'
import { fileURLToPath } from 'url'

// 自动发现 package 根目录（packages/core）
// runtimeContext.ts 位于 packages/core/src/access/sdk/runtimeContext.ts
// 向上 3 级到达 packages/core
const SDK_DIR = dirname(fileURLToPath(import.meta.url))
const PACKAGE_ROOT = resolve(SDK_DIR, '..', '..', '..')

export interface RuntimeContext {
  workspaceRoot: string
  builtinRoot: string
  pluginRoot: string
  cacheFilePath: string
}

export interface RuntimeContextInput {
  cwd?: string
  workspaceRoot?: string
  builtinRoot?: string
  pluginRoot?: string
  cacheFilePath?: string
}

function resolveFromWorkspace(workspaceRoot: string, pathValue: string | undefined, fallbackAbsolute: string): string {
  if (!pathValue || pathValue.trim().length === 0) {
    // 使用 package 相对路径作为默认值
    return fallbackAbsolute
  }
  if (isAbsolute(pathValue)) {
    return resolve(pathValue)
  }
  return resolve(workspaceRoot, pathValue)
}

export function resolveRuntimeContext(input: RuntimeContextInput = {}): RuntimeContext {
  const baseCwd = input.cwd ?? process.cwd()
  const workspaceRoot = input.workspaceRoot
    ? resolve(baseCwd, input.workspaceRoot)
    : resolve(baseCwd)

  return {
    workspaceRoot,
    builtinRoot: resolveFromWorkspace(workspaceRoot, input.builtinRoot, resolve(PACKAGE_ROOT, 'builtin')),
    pluginRoot: resolveFromWorkspace(workspaceRoot, input.pluginRoot, resolve(PACKAGE_ROOT, 'plugins')),
    cacheFilePath: resolveFromWorkspace(
      workspaceRoot,
      input.cacheFilePath,
      resolve(workspaceRoot, '.neo-designer/state/workflow-registry-cache.json'),
    ),
  }
}

