import { test } from 'node:test'
import { strict as assert } from 'node:assert'
import { dirname, resolve } from 'path'
import { fileURLToPath } from 'url'
import { resolveRuntimeContext } from './runtimeContext.ts'

const TEST_DIR = dirname(fileURLToPath(import.meta.url))
const PACKAGE_ROOT = resolve(TEST_DIR, '..', '..', '..')


test('default pluginRoot resolves relative to package root, not workspace root', () => {
  const cwd = '/tmp/neo-test-workspace'
  const ctx = resolveRuntimeContext({ cwd })
  assert.equal(ctx.pluginRoot, resolve(PACKAGE_ROOT, 'plugins'))
  assert.notEqual(ctx.pluginRoot, resolve(ctx.workspaceRoot, 'plugins'))
})


test('default cacheFilePath resolves relative to workspace root', () => {
  const cwd = '/tmp/neo-test-workspace'
  const ctx = resolveRuntimeContext({ cwd })
  assert.equal(
    ctx.cacheFilePath,
    resolve(ctx.workspaceRoot, '.neo-designer/state/workflow-registry-cache.json'),
  )
})


test('absolute builtinRoot is used as-is', () => {
  const ctx = resolveRuntimeContext({ cwd: '/tmp/ws', builtinRoot: '/custom/builtin' })
  assert.equal(ctx.builtinRoot, resolve('/custom/builtin'))
})


test('relative builtinRoot resolves against workspace root', () => {
  const ctx = resolveRuntimeContext({ cwd: '/tmp/ws', builtinRoot: 'my-builtin' })
  assert.equal(ctx.builtinRoot, resolve(ctx.workspaceRoot, 'my-builtin'))
})


test('whitespace-only builtinRoot falls back to package root default', () => {
  const ctx = resolveRuntimeContext({ cwd: '/tmp/ws', builtinRoot: '   ' })
  assert.equal(ctx.builtinRoot, resolve(PACKAGE_ROOT, 'builtin'))
})
